"""Robustness: estimation on weeks 4-12 of the window, generated by the within-week engine in the w0 = 0.3 arm.

The main run (sim.py) estimates on all T = 12 weeks; in the w0 = 0.3 arm weeks 1-3 are drawn weekly
(their lags reach the pre-sample weeks).  This script keeps the weeks that the engine generates in both
practice (window weeks 3-12) and re-estimates M0 on 1000 replications, so that the difference between arms
cannot be attributed to the weekly-generated first three weeks.  Both arms use the extended
generation interval (w1 Y_{t-1} + w2 Y_{t-2} rescaled to the 9-week panel) as the panel's lag-2 weights.

Usage:  python -I robustness.py --R 1000 --workers 16
"""
from __future__ import annotations

for _v in ("OMP_NUM_THREADS", "OPENBLAS_NUM_THREADS", "MKL_NUM_THREADS", "NUMEXPR_NUM_THREADS"):
    __import__("os").environ.setdefault(_v, "1")

import argparse
import json
import math
import os
import sys
import time
from multiprocessing import get_context

import numpy as np

HERE = os.path.dirname(os.path.abspath(__file__))
CODE = os.path.abspath(os.path.join(HERE, "..", "..", "experiment", "code"))
sys.path.insert(0, HERE)
sys.path.insert(0, CODE)

import dgp  # noqa: E402
import qdgmm  # noqa: E402
import same_week_dgp as sw  # noqa: E402
import scenarios as sc  # noqa: E402

CUT = 3            # drop window weeks 1-3 (t = 3, 4, 5); keep t = 6..14 -> now weeks 4-12


def worker(args):
    rep = args
    p = sc.build_scenarios()[1].params
    geo = dgp.make_geography(p.N)
    seed = sc.seed_for(1, rep)
    out = {"rep": rep}
    for arm, w0 in (("benchmark", 0.0), ("same_week", 0.3)):
        sim = sw.simulate_same_week(p, geo, [seed, 0], [seed, 1], w0)
        sl = slice(2 + CUT, 2 + p.T)
        panel = dgp.build_panel(sim["Yall"][sl], sim["Dall"][sl], geo.W, sim["omega"], geo.cl, w=(0.85, 0.15))
        try:
            r = qdgmm.fit(panel, qdgmm.spec_m0(panel, phi_bar=0.5))
            out[arm] = {"ok": bool(r["ok"]), "beta": {k: float(v) for k, v in r["est"].items()},
                        "se": {k: float(v) for k, v in r["se"].items()}}
        except Exception as e:  # noqa: BLE001
            out[arm] = {"ok": False, "err": type(e).__name__, "beta": {}, "se": {}}
    return out


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--R", type=int, default=1000)
    ap.add_argument("--workers", type=int, default=os.cpu_count() or 4)
    ap.add_argument("--out", default=os.path.join(HERE, "results_weeks4_12.json"))
    a = ap.parse_args()
    t0 = time.time()
    with get_context("spawn").Pool(a.workers) as pool:
        rows = list(pool.imap_unordered(worker, range(a.R), chunksize=5))
    tau = float(np.log(0.8))
    res = {"R": a.R, "weeks": "window weeks 4-12 (t = 6..14 of the simulated window)", "truth": {"tau": tau, "kappa": -0.1}}
    for arm in ("benchmark", "same_week"):
        rec = {"conv": float(np.mean([r[arm]["ok"] for r in rows]))}
        for nm, tr in (("tau", tau), ("kappa", -0.1)):
            e = np.array([r[arm]["beta"].get(nm, np.nan) for r in rows])
            s = np.array([r[arm]["se"].get(nm, np.nan) for r in rows])
            g = np.isfinite(e) & np.isfinite(s) & (s > 0)
            n = int(g.sum())
            cov = float((np.abs(e[g] - tr) <= 2.009575 * s[g]).mean())
            rec[nm] = {"n": n, "bias": float((e[g] - tr).mean()), "bias_mcse": float((e[g] - tr).std(ddof=1) / math.sqrt(n)),
                       "empSD": float((e[g] - tr).std(ddof=1)), "modelSE": float(s[g].mean()),
                       "coverage": cov, "coverage_mcse": math.sqrt(cov * (1 - cov) / n)}
        res[arm] = rec
    with open(a.out, "w", encoding="utf-8") as fh:
        json.dump(res, fh, indent=1)
    print(json.dumps(res, indent=1))
    print("done %.0fs" % (time.time() - t0))


if __name__ == "__main__":
    main()
